/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']
r,g,b = d[...,0].astype(int),d[...,1].astype(int),d[...,2].astype(int)
blue = (b>100)&(b-r>50)&(b-g>30)
# connected components frame 0 (simple flood fill)
mask = blue[0]
H,W = mask.shape
seen = np.zeros_like(mask, bool)
comps=[]
for y in range(H):
    for x in range(W):
        if mask[y,x] and not seen[y,x]:
            stack=[(y,x)]; seen[y,x]=1; pts=[]
            while stack:
                cy,cx=stack.pop(); pts.append((cy,cx))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=1; stack.append((ny,nx))
            comps.append(pts)
for c in sorted(comps,key=len,reverse=True)[:10]:
    ys=[p[0] for p in c]; xs=[p[1] for p in c]
    print('n=%d x[%d,%d] y[%d,%d] cx=%.1f cy=%.1f'%(len(c),min(xs),max(xs),min(ys),max(ys),np.mean(xs),np.mean(ys)))
\""
